<?php $appealState42=['pending'=>'Chờ biểu quyết','accepted'=>'Được chấp nhận','rejected'=>'Không được chấp nhận','rescue_pending'=>'Chờ xử lý cứu chuỗi','rescued'=>'Đã cứu chuỗi','expired'=>'Hết hạn']; ?>
<section class="sf42-panel sf42-appeal" data-arena-panel="court"><header class="sf42-head"><div><h2>Quy trình giải trình</h2><p>Giải trình sau khi không hoàn thành mục tiêu, không phải đơn xin nghỉ tự động.</p></div><a class="btn secondary" href="#sf42-appeal-form" data-sf42-appeal-open>Gửi giải trình</a></header><div class="sf42-steps"><?php foreach([['1','Gửi lý do','Đính kèm ảnh minh chứng theo quy định.'],['2','Chờ biểu quyết','Thành viên đủ quyền bỏ phiếu.'],['3','Xem kết quả','Theo dõi quyết định và trạng thái chuỗi.']] as [$num,$title,$desc]):?><div><i><?= $num ?></i><strong><?= $title ?></strong><small><?= $desc ?></small></div><?php endforeach;?></div><h3>Lịch sử giải trình của bạn</h3><?php if(empty($sf42OwnAppeals)):?><p class="sf42-note">Bạn chưa có giải trình nào.</p><?php else:?><div class="sf42-list"><?php foreach($sf42OwnAppeals as $a):?><div><span>Tuần <?= sf_h((new DateTimeImmutable($a['week_start']))->format('d/m/Y')) ?><small><?= sf_h(sf_format_time($a['created_at'],'d/m/Y H:i')) ?></small></span><b><?= sf_h($appealState42[$a['status']]??$a['status']) ?></b></div><?php endforeach;?></div><?php endif;?></section>
